<a class="back-link" href="<?= e(url($user && (int) $story['user_id'] === (int) $user['id'] ? '/my-stories' : '/library')) ?>">← <?= $user && (int) $story['user_id'] === (int) $user['id'] ? 'Мои истории' : 'Библиотека' ?></a>
<div class="reader-layout"><aside class="reader-tools"><p class="eyebrow"><?= e(genre_name($story['genre'])) ?></p><h1><?= e($story['title']) ?></h1><p class="muted"><?= e($story['author']) ?> · <?= e(readable_date($story['created_at'])) ?></p><p class="muted"><?= e(page_label($story['page_count'])) ?> · <?= $story['is_public'] ? 'Опубликовано' : 'Только для вас' ?></p><a class="button full-width" href="<?= e(url('/stories/' . $story['id'] . '/pdf')) ?>">Скачать PDF ↓</a><p class="field-hint">PDF сохраняет весь текст. Число страниц может отличаться от выбранного объёма.</p>
<?php if ($user && (int) $story['user_id'] === (int) $user['id']): ?><a class="button secondary full-width" href="<?= e(url('/stories/' . $story['id'] . '/edit')) ?>">Редактировать</a><form method="post" action="<?= e(url('/stories/' . $story['id'] . '/publish')) ?>"><?= csrf_field() ?><input type="hidden" name="is_public" value="<?= $story['is_public'] ? 0 : 1 ?>"><button class="text-button" type="submit"><?= $story['is_public'] ? 'Убрать из библиотеки' : 'Опубликовать в библиотеке' ?></button></form><form method="post" action="<?= e(url('/stories/' . $story['id'] . '/delete')) ?>" data-confirm="Удалить историю? Восстановить её будет нельзя."><?= csrf_field() ?><button class="text-button danger" type="submit">Удалить историю</button></form><?php endif; ?><details class="premise-details"><summary>Исходный замысел</summary><p><?= e($story['premise']) ?></p></details></aside><div class="reading-pages"><?php foreach ($story['pages'] as $index => $page): ?><article class="reading-page"><div class="reading-page-top"><span>Лист <?= $index + 1 ?></span><span aria-hidden="true">✦</span></div><h2><?= e($page['heading']) ?></h2><div class="story-text"><?= story_paragraphs($page['text']) ?></div><div class="reading-page-bottom"><?= $index + 1 ?> / <?= $story['page_count'] ?></div></article><?php endforeach; ?></div></div>
<?php if ($story['is_public']): ?><section class="comments-section" id="comments"><div class="section-heading"><p class="eyebrow">После последней страницы</p><h2>Обсуждение <span class="muted">(<?= count($comments) ?>)</span></h2></div><?php foreach ($comments as $comment): ?><article class="comment" id="comment<?= $comment['id'] ?>"><div class="comment-heading"><strong><?= e($comment['author']) ?></strong><span class="muted"><?= e(readable_date($comment['created_at'])) ?></span></div><p><?= nl2br(e($comment['text'])) ?></p><?php if ($user && (int) $comment['user_id'] === (int) $user['id']): ?><div class="comment-actions"><a href="<?= e(url('/comments/' . $comment['id'] . '/edit')) ?>">Редактировать</a><form method="post" action="<?= e(url('/comments/' . $comment['id'] . '/delete')) ?>" data-confirm="Удалить комментарий?"><?= csrf_field() ?><button class="text-button danger" type="submit">Удалить</button></form></div><?php endif; ?></article><?php endforeach; ?><?php if (!$comments): ?><p class="muted">Пока никто не оставил комментарий. Можно начать обсуждение.</p><?php endif; ?><?php if ($user): ?><form class="comment-form" method="post" action="<?= e(url('/stories/' . $story['id'] . '/comments')) ?>"><?= csrf_field() ?><label class="field">Ваш комментарий<textarea name="text" rows="4" maxlength="2000" required></textarea></label><button class="button" type="submit">Оставить комментарий</button></form><?php else: ?><p><a href="<?= e(url('/login')) ?>">Войдите</a>, чтобы оставить комментарий.</p><?php endif; ?></section><?php endif; ?>
